import { listSitemapIds } from "@/lib/sitemap-ids";
import { siteConfig } from "@/lib/site-config";

/**
 * Sitemap index at /sitemap-index.xml (/sitemap.xml redirects here: Next reserves that path for app/sitemap.ts). The individual
 * sitemaps are generated by app/sitemap.ts at /sitemap/<id>.xml; robots.txt lists them too.
 */
export async function GET(): Promise<Response> {
  const ids = await listSitemapIds();
  const body = [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
    ...ids.map((id) => `  <sitemap><loc>${siteConfig.url}/sitemap/${id}.xml</loc></sitemap>`),
    "</sitemapindex>",
    "",
  ].join("\n");
  return new Response(body, {
    headers: { "Content-Type": "application/xml; charset=utf-8", "Cache-Control": "public, max-age=3600" },
  });
}
